import { DEFAULT_GAME_CONFIG } from './config';
import { FootPosition, GameConfig, JumpPlan } from './types';

export function chargeDistance(holdSeconds: number, config: GameConfig = DEFAULT_GAME_CONFIG): number {
    if (!Number.isFinite(holdSeconds) || holdSeconds < 0) throw new RangeError('invalid holdSeconds');
    const q = Math.max(0, Math.min(1, (holdSeconds - config.minChargeSeconds) / (config.maxChargeSeconds - config.minChargeSeconds)));
    return config.minJumpDistance + (config.maxJumpDistance - config.minJumpDistance) * q;
}
/** Descending crossing of a horizontal plane, not a render-frame proximity test. */
export function descendingLandingTime(startY: number, topY: number, config: GameConfig = DEFAULT_GAME_CONFIG): number {
    const d = config.verticalVelocity * config.verticalVelocity + 2 * config.gravity * (startY - topY);
    if (!Number.isFinite(d) || d < 0) throw new RangeError('unreachable landing height');
    return (config.verticalVelocity + Math.sqrt(d)) / config.gravity;
}
export function sampleJump(plan: JumpPlan, seconds: number, config: GameConfig = DEFAULT_GAME_CONFIG): FootPosition {
    if (!Number.isFinite(seconds)) throw new RangeError('invalid sample time');
    const t = Math.max(0, Math.min(plan.flightTime, seconds));
    const progress = t / plan.flightTime;
    return Object.freeze({ x: plan.startFoot.x + plan.directionXZ.x * plan.distance * progress,
        z: plan.startFoot.z + plan.directionXZ.z * plan.distance * progress,
        y: plan.startFoot.y + config.verticalVelocity * t - config.gravity * t * t / 2 });
}

import { DEFAULT_GAME_CONFIG } from './config';
import { GameConfig, PlatformSpec, ReplayResult, XZ } from './types';

export function isSafeLanding(point: XZ, platform: PlatformSpec, config: GameConfig = DEFAULT_GAME_CONFIG): boolean {
    const dx = point.x - platform.centerXZ.x, dz = point.z - platform.centerXZ.z;
    if (!Number.isFinite(dx) || !Number.isFinite(dz)) return false;
    if (platform.shape === 'rect') return Math.abs(dx) <= platform.halfExtent.x - config.safeRadius + config.geometryEpsilon &&
        Math.abs(dz) <= platform.halfExtent.z - config.safeRadius + config.geometryEpsilon;
    const r = platform.radius - config.safeRadius;
    return dx * dx + dz * dz <= r * r + config.geometryEpsilon;
}
export function isCenterLanding(point: XZ, platform: PlatformSpec, config: GameConfig = DEFAULT_GAME_CONFIG): boolean {
    return Math.hypot(point.x - platform.centerXZ.x, point.z - platform.centerXZ.z) <= config.centerRadius + config.geometryEpsilon;
}
export function classifyLanding(point: XZ, current: PlatformSpec, target: PlatformSpec,
    config: GameConfig = DEFAULT_GAME_CONFIG): ReplayResult['classification'] {
    if (isSafeLanding(point, target, config)) return isCenterLanding(point, target, config) ? 'target-center' : 'target-normal';
    return isSafeLanding(point, current, config) ? 'current' : 'miss';
}
export interface DistanceInterval { readonly min: number; readonly max: number; }
/** Geometric safety interval along a normalized ray; negative ray distances excluded. */
export function safeRayInterval(start: XZ, direction: XZ, target: PlatformSpec,
    config: GameConfig = DEFAULT_GAME_CONFIG): DistanceInterval | null {
    if (![start.x, start.z, direction.x, direction.z].every(Number.isFinite) ||
        Math.abs(Math.hypot(direction.x, direction.z) - 1) > config.geometryEpsilon) throw new RangeError('invalid ray');
    const offset = { x: start.x - target.centerXZ.x, z: start.z - target.centerXZ.z };
    let min = 0, max = Infinity;
    if (target.shape === 'circle') {
        const r = target.radius - config.safeRadius;
        const b = offset.x * direction.x + offset.z * direction.z;
        const discriminant = b * b - (offset.x * offset.x + offset.z * offset.z - r * r);
        if (discriminant < 0) return null;
        const root = Math.sqrt(discriminant);
        min = Math.max(0, -b - root); max = -b + root;
    } else {
        for (const axis of ['x', 'z'] as const) {
            const half = target.halfExtent[axis] - config.safeRadius;
            if (Math.abs(direction[axis]) < 1e-14) { if (Math.abs(offset[axis]) > half) return null; }
            else {
                const a = (-half - offset[axis]) / direction[axis], b = (half - offset[axis]) / direction[axis];
                min = Math.max(min, Math.min(a, b)); max = Math.min(max, Math.max(a, b));
            }
        }
    }
    return min <= max ? Object.freeze({ min, max }) : null;
}
export function directionToTarget(start: XZ, target: PlatformSpec): XZ {
    const dx = target.centerXZ.x - start.x, dz = target.centerXZ.z - start.z, length = Math.hypot(dx, dz);
    if (!Number.isFinite(length) || length === 0) throw new RangeError('invalid target direction');
    return Object.freeze({ x: dx / length, z: dz / length });
}
export function reachableDistanceInterval(start: XZ, target: PlatformSpec,
    config: GameConfig = DEFAULT_GAME_CONFIG): DistanceInterval | null {
    const interval = safeRayInterval(start, directionToTarget(start, target), target, config);
    if (!interval) return null;
    const min = Math.max(config.minJumpDistance, interval.min), max = Math.min(config.maxJumpDistance, interval.max);
    return min <= max ? Object.freeze({ min, max }) : null;
}
export function assertReachable(start: XZ, target: PlatformSpec, config: GameConfig = DEFAULT_GAME_CONFIG): DistanceInterval {
    const interval = reachableDistanceInterval(start, target, config);
    if (!interval) throw new RangeError(`configuration produces unreachable platform ${target.id} from actual foot`);
    return interval;
}

import { createGameConfig, DEFAULT_GAME_CONFIG } from './config';
import { assertReachable } from './geometry';
import { Xorshift32 } from './random';
import { GameConfig, ModelKey, PlatformSpec, XZ } from './types';

export interface GeneratedPlatform {
    readonly platform: PlatformSpec;
    readonly axis: 'X' | 'Z';
    readonly gap: number;
    readonly centerDistance: number;
}
export class PlatformGenerator {
    private readonly random: Xorshift32;
    private readonly config: Readonly<GameConfig>;
    constructor(seed: number, config: GameConfig = DEFAULT_GAME_CONFIG) {
        this.config = createGameConfig(config); this.random = new Xorshift32(seed);
    }
    initial(): readonly PlatformSpec[] {
        const a = this.make(0, 'block_00', 1, { x: 0, z: 0 });
        const b = this.make(1, 'block_01', 1, { x: this.config.initialTargetDistance, z: 0 });
        assertReachable(a.centerXZ, b, this.config);
        return Object.freeze([a, b]);
    }
    next(previous: PlatformSpec): GeneratedPlatform {
        const axis = this.random.next() < 0.5 ? 'X' : 'Z';
        const scale = this.config.minPlatformScale + (this.config.maxPlatformScale - this.config.minPlatformScale) * this.random.next();
        const gap = this.config.minEdgeGap + (this.config.maxEdgeGap - this.config.minEdgeGap) * this.random.next();
        const model = this.config.modelKeys[Math.floor(this.config.modelKeys.length * this.random.next())];
        const half = previous.shape === 'circle' ? previous.radius : previous.halfExtent[axis === 'X' ? 'x' : 'z'];
        const newHalf = (model === 'block_03' ? Math.min(this.config.platformWidth, this.config.platformDepth) :
            axis === 'X' ? this.config.platformWidth : this.config.platformDepth) * scale / 2;
        const centerDistance = half + newHalf + gap;
        const center = { x: previous.centerXZ.x + (axis === 'X' ? centerDistance : 0),
            z: previous.centerXZ.z + (axis === 'Z' ? centerDistance : 0) };
        const platform = this.make(previous.id + 1, model, scale, center);
        assertReachable(previous.centerXZ, platform, this.config);
        return Object.freeze({ platform, axis, gap, centerDistance });
    }
    private make(id: number, modelKey: ModelKey, horizontalScale: number, centerXZ: XZ): PlatformSpec {
        const base = { id, modelKey, horizontalScale, centerXZ: Object.freeze({ ...centerXZ }), topY: this.config.platformHeight };
        return modelKey === 'block_03' ? Object.freeze({ ...base, shape: 'circle',
            radius: Math.min(this.config.platformWidth, this.config.platformDepth) * horizontalScale / 2 }) :
            Object.freeze({ ...base, shape: 'rect', halfExtent: Object.freeze({ x: this.config.platformWidth * horizontalScale / 2,
                z: this.config.platformDepth * horizontalScale / 2 }) });
    }
}

